  values ('ME', 'short_answer', 'Define buffer system and explain its importance in maintaining blood pH. (3 marks)', 'A buffer system is a solution of a weak acid and its conjugate base (or a weak base and its conjugate acid) that resists a change in pH when small amounts of acid or alkali are added. In blood, the main buffer is carbonic acid-bicarbonate: extra H+ combines with HCO3- to form H2CO3, which breaks into CO2 (exhaled by the lungs) and water; extra OH- is neutralised by H2CO3. Phosphate and protein buffers (including haemoglobin) also help. These buffers keep blood pH within the narrow range 7.35-7.45, preventing acidosis or alkalosis, which would disturb enzymes, nerve function and oxygen transport.', null, '[{"point": "Buffer: a solution of a weak acid and its salt (conjugate base) that resists change in pH when small amounts of acid or base are added", "marks": 1}, {"point": "Main blood buffer: carbonic acid-bicarbonate (also phosphate, proteins/haemoglobin); H+ + HCO3- <-> H2CO3 <-> CO2 + H2O", "marks": 1}, {"point": "Keeps blood pH 7.35-7.45; prevents acidosis/alkalosis, protects enzyme function; works with lungs and kidneys", "marks": 1}]'::jsonb, (select id from public.subjects where slug = 'general-subject-knowledge'),
    (select t.id from public.topics t where t.subject_id = (select id from public.subjects where slug = 'general-subject-knowledge') and t.slug = 'medical-science-general-subject-knowledge'), (select id from public.exam_papers where code = 'me-technical-2'), 'standard', 3,
