  values ('ME', 'short_answer', 'Describe the changes that occur in the uterine lining throughout the menstrual cycle. (3 marks)', 'Menstrual phase (about days 1-5): when progesterone and oestrogen fall, the functional layer of the endometrium breaks down and is shed with blood as menstruation. Proliferative (follicular) phase (about days 6-14): oestrogen from the developing follicle stimulates the endometrium to regenerate and thicken, with growth of glands and spiral arteries. Secretory (luteal) phase (about days 15-28): after ovulation, progesterone from the corpus luteum makes the lining thicker, richly supplied with blood and secreting nutrients, ready for implantation. If no fertilisation occurs, the corpus luteum degenerates, hormone levels drop and the cycle restarts with menstruation.', null, '[{"point": "Menstrual phase (days 1-5): fall in progesterone and oestrogen; functional endometrium breaks down and is shed with blood", "marks": 1}, {"point": "Proliferative phase (days 6-14): oestrogen from growing follicle rebuilds and thickens endometrium; glands and blood vessels grow", "marks": 1}, {"point": "Secretory phase (days 15-28): progesterone from corpus luteum makes lining thicker, more vascular and glandular, ready for implantation; if no pregnancy, corpus luteum degenerates", "marks": 1}]'::jsonb, (select id from public.subjects where slug = 'general-subject-knowledge'),
    (select t.id from public.topics t where t.subject_id = (select id from public.subjects where slug = 'general-subject-knowledge') and t.slug = 'medical-science-general-subject-knowledge'), (select id from public.exam_papers where code = 'me-technical-2'), 'standard', 3,
